# filename: recompute_default_radius.py

def extract_house_positions(file_path):
    with open(file_path, 'r') as f:
        lines = [line.rstrip('\n') for line in f]
    road_idx = None
    for i, line in enumerate(lines):
        if '-' in line:
            road_idx = i
            break
    if road_idx is None:
        raise RuntimeError('Road line not found')
    n = len(lines[road_idx])
    pos = set()
    for neighbor in (road_idx - 1, road_idx + 1):
        if 0 <= neighbor < len(lines):
            line = lines[neighbor]
            for j in range(min(len(line), n)):
                if line[j] == 'H':
                    pos.add(j)
    return sorted(pos)


def min_points_to_hit_intervals(houses, r=3):
    intervals = [(p - r, p + r) for p in houses]
    intervals.sort(key=lambda x: x[1])
    count = 0
    current_point = None
    for (l, rgt) in intervals:
        if current_point is None or current_point < l:
            current_point = rgt
            count += 1
    return count

